style:
@import url('https://googleapis.com');

/* =========================================
   MEMENTO MIDDLE HEADER (ABOVE BLOCK)
   ========================================= */
.memento-page-header {
    text-align: center;
    width: 100%;
    margin-bottom: 24px;
}

.memento-page-header h1 {
    margin: 0;
    font-size: 44px; /* Slightly increased for script font clarity */
    font-weight: 900; /* Script fonts usually display best at a normal weight */
    letter-spacing: normal; /* Restored script tracking for natural link cursive strokes */
    color: #31183b;
    font-family: 'Petit Formal Script', cursive, sans-serif;
}

/* =========================================
   MEMENTO HERO CORE CONTAINER
   ========================================= */
.memento-hero {
    position: relative;
    width: 100%;
    min-height: 185px; 
    overflow: hidden;
    border-radius: 12px;
    background: linear-gradient(105deg, #f4eef5 0%, #f6eaf0 35%, #faf1f3 65%, #fff4ee 100%);
    color: #442a47; 
    padding: 30px 32px;
    box-sizing: border-box;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

/* =========================================
   LEFT SIDE TEXT CONTENT
   ========================================= */
.memento-hero-content {
    position: relative;
    z-index: 5;
    flex: 1;
    max-width: 60%;
}

.memento-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.memento-logo {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: rgba(68, 42, 71, 0.08);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(68, 42, 71, 0.15);
    color: #442a47;
}

.memento-subtitle {
    margin: 0;
    font-size: 14px;
    font-weight: 500;
    color: #633b52;
}

.memento-welcome {
    margin-top: 20px;
}

.memento-welcome h2 {
    margin: 0 0 6px;
    font-size: 16px;
    font-weight: 600;
    color: #442a47;
}

.memento-welcome p {
    margin: 0;
    font-size: 12.5px;
    line-height: 1.5;
    color: #633b52;
    max-width: 480px;
}

/* =========================================
   PREMIUM HIGH-PERFORMANCE LINK BUTTON 
   ========================================= */
.memento-btn-track {
    position: relative;
    display: inline-flex;
    margin-top:10px;
    align-items: center;
    gap: 15px;
    background: #442a47;
    color: #ffffff !important;
    text-decoration: none !important;
    padding: 10px 25px;
    font-size: 13px;
    font-weight: 600;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 4px 14px rgba(68, 42, 71, 0.15);
    transition: transform 0.2s cubic-bezier(0.25, 1, 0.5, 1), 
                box-shadow 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

/* Shimmer overlay effect line */
.memento-btn-track::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.15),
        transparent
    );
    transition: none;
}

.memento-btn-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* --- Animation Hover States --- */
.memento-btn-track:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(68, 42, 71, 0.28);
}

/* Trigger shifting line animation loop on hover */
.memento-btn-track:hover::before {
    left: 100%;
    transition: left 0.65s cubic-bezier(0.25, 1, 0.5, 1);
}

/* Smooth forward spring pop for the icon */
.memento-btn-track:hover .memento-btn-icon {
    transform: translateX(4px) scale(1.1);
}

/* Tactile push mechanism on click */
.memento-btn-track:active {
    transform: translateY(1px);
    box-shadow: 0 2px 8px rgba(68, 42, 71, 0.2);
}

/* =========================================
   RIGHT SIDE GRAPHICS LAYERING
   ========================================= */
.memento-graphics-wrapper {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    width: 50%;
    z-index: 2;
    overflow: hidden;
}

.memento-sun {
    position: absolute;
    width: 56px;
    height: 56px;
    right: 70px;
    bottom: 45px;
    border-radius: 50%;
    background: #ffeba2;
    z-index: 1;
    box-shadow: 0 0 35px rgba(255, 235, 162, 0.5);
}

.memento-mountains {
    position: absolute;
    bottom: -2px;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 2;
    pointer-events: none;
}

.memento-quote {
    position: absolute;
    z-index: 4;
    right: 170px;
    top: 25px;
    text-align: center;
    font-family: 'Georgia', serif;
    font-size: 14px;
    font-style: italic;
    color: #633b52; 
    line-height: 1.3;
    pointer-events: none;
}

.memento-quote span {
    display: block;
}

.quote-text-top {
    font-weight: 400;
}

.quote-text-bottom {
    font-size: 15px;
    font-weight: 600;
    padding-left: 10px;
}

/* =========================================
   CORE GRID SETUP
   ========================================= */
.memento-dashboard-grid {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr;
    gap: 20px;
    width: 100%;
    box-sizing: border-box;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.memento-main-column, .memento-side-column {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

/* =========================================
   INDIVIDUAL CARDS WITH CUSTOM BACKGROUNDS
   ========================================= */
.memento-card {
    border: 1px solid rgba(0, 0, 0, 0.05);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 0 8px 24px rgba(70, 45, 55, 0.03);
    display: flex;
    flex-direction: column;
}

/* Darkened Card Background Themes */
.purple-card-bg { background-color: #f3e6f7; }
.orange-card-bg { background-color: #fbece1; }
.green-card-bg { background-color: #e6f6ed; }
.blue-card-bg   { background-color: #eef2fc; }

/* Card Header Configuration */
.memento-card-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 20px;
}

.memento-header-text h3 {
    margin: 0;
    font-size: 15px;
    font-weight: 700;
    color: #271426;
}

.memento-header-text p {
    margin: 2px 0 0 0;
    font-size: 12px;
    color: #72606e;
}

/* Header Icon Box Palettes */
.memento-icon-box {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
}
.purple-bg { background: #e9c8f7; color: #8c3bb1; }
.orange-bg { background: #fad5bd; color: #cf672a; }
.green-bg { background: #c6ebd5; color: #2da15f; }
.action-bg { background: #cedbfc; color: #3260cc; }

/* =========================================
   LIST LINKS STYLE
   ========================================= */
.memento-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.memento-row-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.5);
    background: #ffffff;
    text-decoration: none !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.02);
    transition: all 0.2s ease;
}

.memento-row-item:hover {
    background: #fffbf9;
    border-color: #e77e41;
    transform: translateX(3px);
}

.item-info {
    display: flex;
    align-items: center;
    gap: 12px;
}

/* Bullet icon containers */
.item-bullet {
    width: 20px;
    height: 20px;
    border-radius: 5px;
    display: inline-block;
    flex-shrink: 0;
    border: 1px solid rgba(0,0,0,0.06);
}
.purple-bullet { background: #f1d3fc; border-color: #ca97e0; }
.orange-bullet { background: #fde0cc; border-color: #f2aa79; }
.blue-bullet { background: #d7e5fa; border-color: #92b8f4; }
.green-bullet { background: #cef5dd; border-color: #8ce4b1; }
.peach-bullet { background: #fde4d0; border-color: #f3b17c; }

.item-title-group {
    display: flex;
    flex-direction: column;
}

.item-main-title {
    font-size: 13.5px;
    font-weight: 600;
    color: #49334c;
}

.item-sub-title {
    font-size: 11.5px;
    color: #7d6b7a;
    margin-top: 1px;
}

.memento-chevron {
    color: #9e899b;
    font-size: 18px;
    font-weight: bold;
}

/* =========================================
   QUICK ACCESS GRID PATTERN
   ========================================= */
.memento-grid-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    height:280px;
}

.grid-btn-item {
    background: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.04);
    border-radius: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 18px 10px;
    text-align: center;
    text-decoration: none !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.02);
    transition: all 0.2s ease;
}

.grid-btn-item:hover {
    background: #ffffff;
    border-color: #bfaebc;
    box-shadow: 0 4px 12px rgba(70,40,50,0.08);
    transform: translateY(-2px);
}

.grid-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 8px;
    background: #fdfdfe;
    border: 1px solid rgba(0,0,0,0.03);
}

.grid-btn-item span {
    font-size: 12px;
    font-weight: 600;
    color: #49334c;
}

.purple-text { color: #8c3bb1; }
.green-text { color: #2da15f; }
.blue-text { color: #3260cc; }
.peach-text { color: #cf672a; }

/* =========================================
   RESPONSIVE
   ========================================= */
@media (max-width: 992px) {
    .memento-dashboard-grid {
        grid-template-columns: 1fr;
    }
}
